import{_ as s,a0 as o,w as a,s as u,ao as p,I as n,x as t,a1 as r,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"工程师和市场营销人员之间能够相互学习什么？ | LCTT x X-CMD","titleTemplate":false,"description":"工程师和市场营销人员之间能够相互学习什么？ | LCTT (201704) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"工程师和市场营销人员之间能够相互学习什么？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"工程师和市场营销人员之间能够相互学习什么？ | LCTT (201704) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201704/20170110 What engineers and marketers can learn from each other","title":"工程师和市场营销人员之间能够相互学习什么？","tag":"201704","desc":""},"relativePath":"201704/20170110 What engineers and marketers can learn from each other.md","filePath":"[post].md"}'),m={name:"201704/20170110 What engineers and marketers can learn from each other.md"};function d(f,e,T,g,k,C){const l=o("Link");return a(),u("div",null,[e[24]||(e[24]=p('<h1 id="工程师和市场营销人员之间能够相互学习什么" tabindex="-1">工程师和市场营销人员之间能够相互学习什么？ <a class="header-anchor" href="#工程师和市场营销人员之间能够相互学习什么" aria-label="Permalink to “工程师和市场营销人员之间能够相互学习什么？”">​</a></h1><blockquote><p>营销人员觉得工程师在工作中都太严谨了；而工程师则认为营销人员毫无用处。但是他们都错了。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/business/BIZ_fortunecookie3.png?itok=dlRX4vO9" alt="What engineers and marketers can learn from each other" title="What engineers and marketers can learn from each other"></p><p>图片来源：opensource.com</p><p>在 B2B 行业从事多年的销售实践过程中，我经常听到工程师对营销人员的各种误解。下面这些是比较常见的：</p><ul><li>“搞市场营销真是浪费钱，还不如把更多的资金投入到实际的产品开发中来。”</li><li>“那些营销人员只是一个劲儿往墙上贴各种广告，还祈祷着它们不要掉下来。这么做有啥科学依据啊？”</li><li>“谁愿意去看哪些广告啊？”</li><li>“对待一个营销人员最好的办法就是不听，不看，也不理睬。”</li></ul><p>这是我最感兴趣的一点：</p><p><em>“市场营销无足轻重。”</em></p><p>最后一点说的不对，而且不仅如此，它实际上是阻碍一个公司创新的巨大绊脚石。</p><p>我来跟大家解释一下原因吧。</p><h3 id="看到自己的身影" tabindex="-1">看到自己的身影 <a class="header-anchor" href="#看到自己的身影" aria-label="Permalink to “看到自己的身影”">​</a></h3><p>这些工程师的的评论让我十分的苦恼，因为我从中看到了自己当年的身影。</p><p>你们知道吗？我曾经也跟你们一样是一位自豪的技术极客。我在 Rensselaer Polytechnic 学院的电气工程专业本科毕业后便在美国空军担任军官开始了我的职业生涯，而且美国空军在那段时间还发动了沙漠风暴行动。在那里我主要负责开发并部属一套智能的实时战况分析系统，用于综合几个的数据源来构建出战场态势。</p><p>在我离开空军之后，我本打算去麻省理工学院攻读博士学位。但是上校强烈建议我去报读这个学校的商学院。“你真的想一辈子待实验室里吗？”他问我。“你想就这么去大学里当个教书匠吗？Jackie ，你在组织管理那些复杂的工作中比较有天赋。我觉得你非常有必要去了解下 MIT 的斯隆商学院。”</p><p>我觉得自己也可以同时参加一些 MIT 技术方面的课程，因此我采纳了他的建议。然而，如果要参加市场营销管理方面的课程，我还有很长的路要走，这完全是在浪费时间。因此，在日常工作学习中，我始终是用自己所擅长的分析能力去解决一切问题。</p><p>不久后，我在波士顿咨询集团公司做咨询顾问工作。在那六年的时间里，我经常听到大家对我的评论： “Jackie ，你太没远见了。考虑问题也不够周全。你总是通过自己的分析去找答案。”</p><p>确实如此啊，我很赞同他们的想法——因为这个世界的工作方式本该如此，任何问题都要基于数据进行分析，不对吗？直到现在我才意识到（我多么希望自己早一些发现自己的问题）自己以前惯用的分析问题的方法遗漏了很多重要的东西：开放的心态、艺术修养、情感——人和创造性思维相关的因素。</p><p>我在 2001 年 9 月 11 日加入达美航空公司不久后，被调去管理消费者市场部门，之前我意识到的所有问题变得更加明显。市场方面本来不是我的强项，但是在公司需要的情况下，我也愿意出手相肋。</p><p>但是突然之间，我一直惯用的方法获取到的分析结果却与实际情况完全相反。这个问题导致上千人（包括航线内外的人）受到影响。我忽略了一个很重要的人本身的情感因素。我所面临的问题需要各种各样的解决方案才能处理，而不是简单的从那些死板的数据中就能得到答案。</p><p>那段时间，我快速地学到了很多东西，因为如果我们想把达美航空公司恢复到正常状态，还需要做很多的工作——市场营销更像是一个以解决问题为导向、以用户为中心的充满挑战性的大工程，只是销售人员和工程师这两大阵营都没有迅速地意识到这个问题。</p><h3 id="两大文化差异" tabindex="-1">两大文化差异 <a class="header-anchor" href="#两大文化差异" aria-label="Permalink to “两大文化差异”">​</a></h3>',21)),n("p",null,[e[1]||(e[1]=t("工程管理和市场营销之间的这个“巨大鸿沟”确实是根深蒂固的，这跟（著名的科学家、小说家） C.P. Snow 提出的",-1)),r(l,{href:"https://en.wikipedia.org/wiki/The_Two_Cultures#Implications_and_influence"},{default:i(()=>[...e[0]||(e[0]=[t("“两大文化差异”问题",-1)])]),_:1}),e[2]||(e[2]=t("很相似。具有科学素质的工程师和具有艺术细胞的营销人员操着不同的语言，不同的文化观念导致他们不同的价值取向。",-1))]),n("p",null,[e[4]||(e[4]=t("但是，事实上他们比想象中有更多的相似之处。一个由微软、谷歌和美国国家科学基金会共同赞助的华盛顿大学的",-1)),r(l,{href:"https://faculty.washington.edu/ajko/papers/Li2015GreatEngineers.pdf"},{default:i(()=>[...e[3]||(e[3]=[t("最新研究",-1)])]),_:1}),e[5]||(e[5]=t("发现了“一个伟大软件工程师必须具备哪些优秀的素质”，毫无疑问，一个伟大的销售人员同样也应该具备这些素质。例如，专家们给出的一些优秀品质如下：",-1))]),e[25]||(e[25]=p('<ul><li>充满激情</li><li>性格开朗</li><li>强烈的好奇心</li><li>技艺精湛</li><li>解决复杂难题的能力</li></ul><p>这些只是其中很小的一部分！当然，并不是所有的素质都适用于市场营销人员，但是如果用文氏图来表示这“两大文化”的交集，就很容易看出营销人员和工程师之间的关系要远比我们想象中密切得多。他们都是竭力去解决与用户或客户相关的难题，只是他们所采取的方式和角度不一致罢了。</p><p>看到上面的那几点后，我深深的陷入思考：<em>要是这两类员工彼此之间再多了解对方一些会怎样呢？这会给公司带来很强大的动力吧？</em></p><p>确实如此。我在红帽公司就亲眼看到过样的情形，我身边都是一些早些年肯定被我当成“想法疯狂”而无视的人。而且我猜销售人员看到工程师后（同时或某一次），心想，“这些数据呆瓜，真是只见树木不见森林。”</p><p>现在我才明白了公司里有这两种人才的重要性。在现实工作当中，工程师和营销人员都是围绕着客户、创新及数据分析来完成工作。如果他们能够懂得相互尊重、彼此理解、相辅相成，那么我们将会看到公司里所产生的那种积极强大的动力，这种超乎寻常的革新力量要远比两个独立的团队强大得多。</p><h3 id="听一听疯子-和呆瓜-的想法" tabindex="-1">听一听疯子（和呆瓜）的想法 <a class="header-anchor" href="#听一听疯子-和呆瓜-的想法" aria-label="Permalink to “听一听疯子（和呆瓜）的想法”">​</a></h3><p>成功案例：《开放式组织》</p><p>在红帽任职期间，我的主要工作就是想办法提升公司的品牌影响力——但是就是给我一百万年我也不会想到让公司的 CEO 去写一本书。我把公司多个部门的“想法疯狂”的同事召集在一起，希望他们帮我设计出一个新颖的解决方案来提升公司的影响力，结果他们提出让公司的 CEO 写书这样一个想法。</p>',8)),n("p",null,[e[7]||(e[7]=t("当我听到这个想法的时候，我很快意识到这正是典型的红帽方式：它将对整个开源社区的从业者带来很重要的参考价值，同时也有助于宣扬开源精神。通过优先考虑这两方面的作用，我们提升了红帽在整个开源软件世界中的品牌价值——红帽是一个可靠的随时准备着为客户在",-1)),r(l,{href:"https://opensource.com/open-organization/16/7/future-belongs-open-leaders"},{default:i(()=>[...e[6]||(e[6]=[t("数字化颠覆",-1)])]),_:1}),e[8]||(e[8]=t("年代指明方向的公司。",-1))]),e[26]||(e[26]=n("p",null,"这一点才是主要的：确切的说是指导红帽工程师解决代码问题的共同精神力量。 Red Hatters 小组敦促我出版《开放式组织》，这显示出来自内部和外部社区的程序员共同推动整个开源社区发展的强大动力之一：那就是强烈的共享欲望。",-1)),e[27]||(e[27]=n("p",null,"最后，要把《开放式组织》这本书完成，还需要大家的共同能力，包括工程师们强大的数据分析能力和营销人员美好的艺术素养。这个项目让我更加坚定自己的想法，工程师和营销人员有更多的相似之处。",-1)),e[28]||(e[28]=n("p",null,"但是，有些东西我还得强调下：开放模式的实现，要求公司上下没有任何偏见，不能偏袒工程师和市场营销人员任何一方文化。一个更加理想的开放式环境能够促使员工之间和平共处，并在这个组织规定的范围内点燃大家的热情。",-1)),e[29]||(e[29]=n("p",null,"这对我来说如春风拂面。",-1)),e[30]||(e[30]=n("hr",null,null,-1)),e[31]||(e[31]=n("p",null,"作者简介：",-1)),e[32]||(e[32]=n("p",null,[n("img",{src:"https://opensource.com/sites/default/files/styles/profile_pictures/public/pictures/portrait_jackieyeaney_400x600.jpg?itok=zV4bnrzI",alt:""})],-1)),e[33]||(e[33]=n("p",null,"Jackie Yeaney —— Ellucian 公司市场总监",-1)),e[34]||(e[34]=n("hr",null,null,-1)),n("p",null,[e[10]||(e[10]=t("via: ",-1)),r(l,{href:"https://opensource.com/open-organization/17/1/engineers-marketers-can-learn"},{default:i(()=>[...e[9]||(e[9]=[t("https://opensource.com/open-organization/17/1/engineers-marketers-can-learn",-1)])]),_:1})]),n("p",null,[e[15]||(e[15]=t("作者：",-1)),r(l,{href:"https://opensource.com/users/jackie-yeaney"},{default:i(()=>[...e[11]||(e[11]=[t("Jackie Yeaney",-1)])]),_:1}),e[16]||(e[16]=t(" 译者：",-1)),r(l,{href:"https://github.com/rusking"},{default:i(()=>[...e[12]||(e[12]=[t("rusking",-1)])]),_:1}),e[17]||(e[17]=t(" 校对：",-1)),r(l,{href:"https://github.com/Bestony"},{default:i(()=>[...e[13]||(e[13]=[t("Bestony",-1)])]),_:1}),e[18]||(e[18]=t(", ",-1)),r(l,{href:"https://github.com/wxy"},{default:i(()=>[...e[14]||(e[14]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[21]||(e[21]=t("本文由 ",-1)),r(l,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[19]||(e[19]=[t("LCTT",-1)])]),_:1}),e[22]||(e[22]=t(" 原创编译，",-1)),r(l,{href:"https://linux.cn/"},{default:i(()=>[...e[20]||(e[20]=[t("Linux中国",-1)])]),_:1}),e[23]||(e[23]=t(" 荣誉推出",-1))])])}const P=s(m,[["render",d]]);export{y as __pageData,P as default};
